import { Hono } from 'hono';
import { zValidator } from '../../common/validate.js';
import { requirePermission } from '../../common/auth.js';
import { grantsController } from './grants.controller.js';
import { createGrantTypeSchema, recordDisbursementSchema } from './grants.schema.js';
export const grantsRoutes = new Hono();
grantsRoutes.get('/types', requirePermission('grants.view'), grantsController.listTypes);
grantsRoutes.post('/types', requirePermission('grants.record'), zValidator('json', createGrantTypeSchema), grantsController.createType);
grantsRoutes.get('/disbursements', requirePermission('grants.view'), grantsController.listDisbursements);
grantsRoutes.get('/disbursements/:id', requirePermission('grants.view'), grantsController.getDisbursementById);
grantsRoutes.post('/disbursements', requirePermission('grants.record'), zValidator('json', recordDisbursementSchema), grantsController.recordDisbursement);
